// build wave-1 spec for kumitate round 63 (40 seats, v1 band 32-64): build + first falsifiers
import { writeFileSync } from 'node:fs';
import { LANE, FLEET, BASE, FREEZE, ROUTE, context, mk } from './common.mjs';

const items = [];
const add = mk(items);
const W = `${LANE}/.ufo/waves/round-63/w1`;
const B = `${LANE}/.ufo/waves/round-63/build`;
const ST = `${ROUTE.staged}/knowledge/corpus/knowledge/multi-agent-coordinator-topologies.md`;
const CAP = ROUTE.caps;
const NORM = `normalise both sides before matching a quote: strip HTML tags and <script>/<style>, decode &amp; &lt; &gt; &quot; &#39; &nbsp;, map curly quotes to ASCII quotes and en/em dashes to "-", delete "*", "_" pairs "**"/"__" and backticks, collapse all whitespace to one space (the frozen counter's norm() in ${ROUTE.c2probe} is the reference; read it)`;

// ======================= SCOUTS (5) =======================
add('K63ScoutBailianOpen', 'scout', `Independently open the Bailian coordinator-topology page and compare it with the L1's capture.
1. Fetch https://docs.bailian.console.aliyun.com/zh/model-studio/managed-agents-multiagent.md with curl -sSL (UA 'Mozilla/5.0 (kumitate-r63)'), record HTTP status, Content-Type, Last-Modified/ETag if any, byte size and sha256sum. Compare with ${CAP}/bailian-managed-agents-multiagent.md (sha256 7ea4396645e3b1c89a3fd984ea095dabd75c2e23e8f376ec2211c1b855ec37e6, 3388 bytes). Also fetch the same page without the .md suffix and the site's llms.txt entry for it; say whether the three agree on the roster facts.
2. Locate, in the capture, exact located quotes for these facts (Chinese text is the evidence; each quote <= 25 words, verbatim, with the heading it sits under): (a) coordinator is the only supported topology type; (b) agents list is 1-20 entries and an empty array clears the roster; (c) a roster entry is type agent or self, self at most once; (d) id <= 64 characters and version >= 1, defaulting to latest when omitted; (e) with no multiagent field or an empty roster the agent runs as a single agent. ${NORM}. For each quote run a grep/python check proving it occurs in the capture exactly once or say how often.
3. Check lane overlap: the lane registry already holds S131 (managed-agents-introduction, a DIFFERENT page, ${LANE}/corpus/SOURCES.md line with | S131 |). State whether any fact above is already in ${LANE}/corpus/knowledge/*.md.
Write the quotes as a ready-to-paste list "- S196 — \\"…\\"" in your report (S196 is the id this document will take).`, ['coverage'], 'open S196 source');

add('K63ScoutArxivOpen', 'scout', `Independently open the arXiv scaling study at the VERSION-PINNED URL and compare with the L1's capture.
1. Fetch https://arxiv.org/html/2512.08296v3 (and https://arxiv.org/abs/2512.08296v3) with curl -sSL; record HTTP status, size, sha256sum. Compare the html with ${CAP}/arxiv-2512.08296v3.html (sha256 df31beb3a2ae0f9ad2084750b34a05849b2ab418cb8121666ffb8a8a15517223, 663997 bytes). State the version string and date printed in the page ("arXiv:2512.08296v3 ... 08 Apr 2026" is expected), and whether v1/v2 (https://arxiv.org/abs/2512.08296v1 and v2) differ on the sentence "Across 260 configurations spanning six agentic benchmarks" (a prior round's wave first called this a spliced quote; wave 2 of that round corrected it to a version mismatch — settle it with bytes).
2. From the html body (${NORM}) locate and quote verbatim, each <= 25 words with its section, up to 10 facts the topology entry may cite: the 260-configuration / six-benchmark / five-architecture setup; Finance Agent +57% to +80.8%; PlanCraft -70% to -39%; the tool-heavy overhead finding; the 45% single-agent threshold (beta = -0.236, p = 0.004); the max architecture-slope difference 0.023; the Workbench range; BrowseComp-Plus; SWE-bench Verified and Terminal-Bench (Appendix F) numbers. For each quote prove with a script that it occurs in the capture (count occurrences). If a number is not in the page, say NOT FOUND.
3. List the page's own wording for the five architectures and for the coordination-overhead formula, if any.
Ready-to-paste list "- S197 — \\"…\\"" at the end of your report (S197 is the id this document will take).`, ['coverage'], 'open S197 source');

add('K63ScoutStagedDiff', 'scout', `Compare the STAGED shokuknow entry with this round's two captures, claim by claim.
Read ${ST} and the rows S200 and S202 in ${ROUTE.staged}/SOURCES.append.md (read-only; run no campaign tool). The staged entry cites S200 (Bailian, in the package) and S202 (arXiv 2512.08296). In ${CAP} the captures are ${CAP}/bailian-managed-agents-multiagent.md and ${CAP}/arxiv-2512.08296v3.html.
For EVERY factual sentence, number or quote in the staged entry (the roster 1-20 / self at most one / version default; the 260 experiments; the six-row benchmark table incl. the Workbench, SWE-bench Verified -15% to -2%, Terminal-Bench independent +2% and centralized -19%, PlanCraft; the 'r·n' and 'r·n + p·m' overhead formulas; the 0.023 slope difference; the 'above 45% for most models' remark) record: supported (with the located text in the capture and its section) / unsupported (not in the capture) / contradicted (capture says otherwise). ${NORM}. Output a table with one row per claim and a final list "cut before adoption" naming each unsupported or contradicted claim. Do not rewrite the entry.`, ['coverage'], 're-grounding diff');

add('K63ScoutQuarantine', 'scout', `Hand-check the quarantine slice for this lane and give a verdict per row (assimilation contract: quarantined rows are not appendable until hand-checked; bind rows to the lane registry by DOCUMENT identity — normalised URL or DOI — never by S-id equality, QUALITY Q56).
Inputs: ${LANE}/.ufo/waves/round-63/assimilation/quarantine-slice (9 register ids), the register /home/vgpnk/Projects/shokuknow/.ufo/waves/corpus-expansion-1/absent-defect-register.md (read-only), the package rows in ${ROUTE.staged}/SOURCES.append.md, and the lane registry ${LANE}/corpus/SOURCES.md.
For each of the 9 ids: find the package row's URL/DOI and quote cell; map it to a lane row by URL/DOI ("no lane row" is a valid answer); fetch the source (curl/aaron; pdftotext if a PDF) and try to locate the package's quote; verdict PRESENT (quote located: give anchor), ABSENT (source reached, quote not there — fabrication class), or UNVERIFIABLE (could not be fetched — 'unreachable' is not fabrication). Note that S116 is arXiv 2512.08296 (the document C2 cites) and that a previous round found it PRESENT in v3 and ABSENT in v1/v2 §4.1 — re-derive. Output a table and one line per row. Never edit the register or any campaign file.`, ['coverage'], 'quarantine verdicts');

add('K63ScoutStagedScope', 'scout', `Scope-gate the rest of the staged package so the round's lesson can record at least one honest REJECT besides the adopted topology entry.
Read ${LANE}/PROVINCE.md (core / frontier / adjacent bands) and ${ROUTE.staged}/MERGE-REPORT.md. Pick FIVE staged entries from ${ROUTE.staged}/knowledge/corpus/knowledge/ other than multi-agent-coordinator-topologies.md and exactly-once-attribution.md (prefer the ones whose titles touch orchestration: omp-session-sharing-and-mcp-lifecycle, omp-advisor-and-mcp-transports, mcp-stateless-vendor-compatibility, japanese-multi-agent-operations, agent-isolation-substrates-amendment-2026-10-25 …). For each: read it, name its S-ids and which lane rows already hold the same documents (by URL), apply the PROVINCE scope check (core/frontier/adjacent/out) and QUALITY Q1-Q9 (${LANE}/corpus/QUALITY.md entry criteria), and give ADMIT-CANDIDATE / REJECT with a one-line reason and, for REJECT, a flip condition. Do not write into the lane corpus. The L1 will pick the REJECT recorded in the lesson.`, ['coverage'], 'assimilation scope gate');

// ======================= CONNECTORS (3) =======================
add('K63ConnTopologyOverlap', 'connector', `Sibling-overlap scan for the coordinator-topology theme (cross-source pattern finding).
Search the other lanes' registries and corpora for the two documents and the theme: grep -rIl in ${FLEET}/*-shokunin/corpus (SOURCES.md, knowledge/, lessons/) for '2512.08296', 'bailian', 'managed-agents', 'coordinator', 'centralized', 'Independent, Centralized', 'multiagent'. For each hit say which lane holds it, what it claims, and whether this lane absorbing the topology entry would (a) duplicate it, (b) contradict it, or (c) sit in a lane's PROVINCE 'Adjacent' band (kengaku LLM eval, kotoba prompt craft, kama serving, chousa research method). Read ${LANE}/PROVINCE.md adjacency lines. Recommend the exact adjacency sentence this lane should add to its PROVINCE frontier bullet so the entry is framed as orchestration topology DECISIONS (not agent evaluation). Report as a table.`, ['coverage'], 'adjacency scan');

add('K63ConnForgeryClasses', 'connector', `Cross-round pattern: map every forgery or do-nothing class that earlier rounds' counters accepted onto this round's two frozen counters.
Read ${LANE}/corpus/lessons/round-61.md §Mistakes, ${LANE}/corpus/lessons/round-61-verifier-spotcheck.md (R61-V2), round-62-verifier-spotcheck.md, ${LANE}/corpus/QUALITY.md Q54-Q57, ${LANE}/.ufo/waves/round-62/w1/AttackC1C2.md and w1/ReviewClaims.md, and the frozen counters ${ROUTE.c1probe} and ${ROUTE.c2probe} plus ${LANE}/.ufo/waves/round-63/plan.md. Produce a matrix: rows = forgery classes seen (worktree-vs-revision read, substring/count-only checks, hand-written progress file, phantom row outside the registry, fabricated capture, forged capture with recomputed pin, unsatisfiable honest row shape, mixed-state reads, self-authored receipt, circular tip receipt …) and columns = {I1..I6, T1..T7}; mark which arm kills it and which arm does NOT. List every class no arm kills, with a concrete cheap forgery for each. Do not edit the counters; the L1 ratchets the gate/controls.`, ['operability', 'coverage'], 'forgery matrix');

add('K63ConnIntegrationMap', 'connector', `Integration map: every file and number that must change when the lane adds (a) the tool scripts/inline-dispatch-evidence.mjs, (b) the entry corpus/knowledge/multi-agent-coordinator-topologies.md with two registry rows S196/S197 and two captures, (c) a corpus/lessons/round-63.md lesson, (d) a round-63-verifier-spotcheck.md the closure will add later.
Trace, by reading the code (do not guess): scripts/proxy-check.mjs (the A/C/C2/C2_total terms, RE_RUNNABLE over walkFiles, GATE_PINS, the kumitate-proxy-v1 stanza and kumitate-gate-pins-v1 block in ${LANE}/SCORECARD.md), scripts/readme-map.mjs + .ufo/pins/readme-map.json, scripts/cite-sources.mjs, scripts/source-capture.mjs + .ufo/pins/source-captures.json, scripts/counter-pins.mjs, scripts/sources-check.mjs, ${LANE}/SKILL.md (gate registry, verifiable checklist), corpus/README.md (coverage map, frontier), PROVINCE.md. Output an ordered checklist: file, exact edit, the gate that reads it, and the command that proves it clean. State the current drift at base: ${LANE}/.ufo/waves/round-63/base/proxy-before.txt and readme-map-before.txt. Also compute what the proxy stanza's A, C2 and C2_total will read after the round adds N files (give the formula, from the code, and the base values).`, ['operability'], 'integration map');

// ======================= EXECUTORS (13) =======================
add('K63ExecGateForgery', 'executor', `Forge the gate, then make the forgery fail.
Gate: ${ROUTE.gate} (read it fully; contract in its header). 1. In a scratch copy build the CHEAPEST faithful forgery a lane could write: a sessions root with hand-written <Seat>.jsonl transcripts that contain the '# Seat <name>', the context head, the task tail, a session header, a yield tool call and a session_exit normal record, plus a dispatcher.log with a 'spawned' and 'done' line, plus 40 plausible seat reports — all without any seat having run (see ${LANE}/.ufo/waves/round-63/controls/inline/honest for the shape). Show the gate reads CLEAN on it (that is the known limit). 2. Measure what a REAL transcript has that the forgery lacks, from the real host store ~/.omp/agent/sessions/**/*.jsonl (e.g. the kengaku r35 / mori r47 w2 seats): count of assistant messages, toolResult messages, model_usage custom records, thinking blocks, timestamp spread, file size, tool-call/toolResult pairing by id, monotonic timestamps. Choose 3-5 cheap structural checks that every real finished seat satisfies (verify on at least 100 real transcripts, report the pass rate and the failures) and that the cheap forgery fails. 3. Implement them in a COPY of the gate under ${B}/K63ExecGateForgery/inline-dispatch-evidence.mjs (never in scripts/), keep its selftest green, extend the selftest with the forgery cases, and run the patched copy over every real completed wave on this host (loop in ${LANE}/.ufo/waves/round-63/controls/inline-real-hosts.txt) to prove no new false positive on kengaku r35 build/falsify and mori r47 w2. 4. Emit a unified diff ${B}/K63ExecGateForgery/gate.patch, plus new control directories under ${B}/K63ExecGateForgery/controls/ in the same layout as controls/inline/<case>/ (lane/, sessions/, dispatcher.log, expect) for each forgery your checks kill. Report pass rates and the diff size.`, ['operability'], 'ratchet: cheap-forgery binds');

add('K63ExecRealWavesDrift', 'executor', `Classify every DRIFT the gate reads on real completed waves — false positive of the gate, or a real defect of that wave?
Input: ${LANE}/.ufo/waves/round-63/controls/inline-real-hosts.txt (souji r26/27/28, tabi r27/28, kaidoku r35, mado r39, tsukuroi r37, mori r47 w1, tameshi r45 w1/w2, kasegi, kengaku r33/34 read DRIFT; kengaku r35 and mori r47 w2 read CLEAN). For each wave run ${ROUTE.gate} with --root <lane> --round N --wave W and read the FINDING lines; open the host store ~/.omp/agent/sessions/*/ and answer WHY: is there no transcript for the seats (older dispatcher / different session store / seats spawned by another orchestrator session), is the prompt shape different (no '# Seat <name>' marker, different context), a respawn duplicate (<Name>-2.jsonl, <Name>-3.jsonl — SESSION_AMBIGUOUS: find how the duplicates arose from /fast/scratch/hyaku-run7/dispatcher.log and dispatcher.py), a missing spawned/done log line (the log started later?), a missing report. Output a table: wave | finding classes | cause | gate-fault or wave-fault | evidence. Propose gate changes ONLY for gate-fault rows (patch text in ${B}/K63ExecRealWavesDrift/). Do not edit scripts/.`, ['operability'], 'real-data false-positive audit');

add('K63ExecSelftestMutants', 'executor', `Mutation battery for the gate's own selftest.
Copy ${ROUTE.gate} into ${B}/K63ExecSelftestMutants/work/ and write a runner ${B}/K63ExecSelftestMutants/mutants.mjs that applies ONE single-literal mutant at a time (>= 30: flip each comparison/regex/constant/boolean in inspect(): the 64-byte report floor, the 120-char tail, the 200-char context head, 'normal' exit kind, 'yield', each finding id's guard, the dispatcher-log regexes, the parents-set size test, the sessions===0 test, the rev-mode read, etc.), runs 'node <copy> --selftest' (timeout 60s, in its own process) and records killed (selftest exit != 0) or SURVIVED. Never mutate the original. Output ${B}/K63ExecSelftestMutants/mutants.tsv (id, line, original -> mutant, outcome) and the list of SURVIVORS with, for each, the selftest case that would kill it (write the case body as a code block). Report kill rate. Equivalent mutants must be argued, not assumed.`, ['operability'], 'gate mutation battery');

add('K63ExecCollisionGuard', 'executor', `Assimilation id-collision guard, proven able to fail (addendum item 10).
Work in ${LANE}/.ufo/waves/round-63/build/K63ExecCollisionGuard/. 1. Re-run the guard: A=<your build dir>; grep -oE '^ {0,3}\\|[[:space:]]*S[0-9]{3,}' ${LANE}/corpus/SOURCES.md | grep -oE 'S[0-9]+' | sort > $A/reg-ids; same for ${ROUTE.staged}/SOURCES.append.md > $A/staged-ids; comm -12 > $A/collisions. Paste both id counts, the collision list (expected: S195 only) and the renumber map the L1 should use: package S200 (Bailian multiagent) -> lane S196 and package S202 (arXiv 2512.08296) -> lane S197 — verify those two lane ids are free, and say which package ids are documents the lane already holds by URL (e.g. package S195 = the MCP Architecture page that lane S125 holds). 2. Prove the guard once: build a scratch registry with an INDENTED row ('  | S002 |' style, 0-3 leading spaces) that the staged set collides with; the guard must print a nonempty collisions file; also show a column-zero-only pattern misses it. Paste the outputs. 3. Report whether any package row's URL equals a lane row's normalised URL (duplicate-URL class E04/W04) for the two rows being adopted.`, ['coverage'], 'collision guard proof');

add('K63ExecRowDraft', 'executor', `Build and validate the registry append block for the two rows this round adopts, in a scratch mirror — no staged row is appended as-is.
Rows (document identity): S196 = the Bailian page https://docs.bailian.console.aliyun.com/zh/model-studio/managed-agents-multiagent.md (capture ${CAP}/bailian-managed-agents-multiagent.md); S197 = the arXiv study https://arxiv.org/html/2512.08296v3 (capture ${CAP}/arxiv-2512.08296v3.html; row anchors the version). Schema: 11 columns (NF=13 in the census): | id | source | kind | tier | scope | anchor | teaches | status | opened | recheck | used-by |, kind in {docs,paper,...} per the existing rows, tier A only if the source is first-party for what it teaches (a vendor's own doc = A for its own contract; the arXiv paper = A), status mined, opened 2026-10-25, recheck a valid ISO date / NNd / symbolic cadence (no prose), used-by exactly corpus/knowledge/multi-agent-coordinator-topologies.md, NO literal or escaped pipe in any cell, the anchor carries a located <= 25-word quote. Mirror the lane: copy ${LANE}/corpus to ${B}/K63ExecRowDraft/validate/corpus (and the entry placeholder file the used-by cell names, an empty stub in the mirror only), append your block inside the Registry table of the mirror's SOURCES.md, and run /home/vgpnk/Projects/shokunin/scripts/sources-census.sh validate --file <mirror>/corpus/SOURCES.md — exit 0 required (paste the output and the exit code). Write the block to ${B}/K63ExecRowDraft/append-block.md and a second copy of both rows with the quote cells exactly as they will appear.`, ['coverage'], 'registry rows validated in scratch');

add('K63ExecCapturePins', 'executor', `Prepare and verify the two source-capture pins.
Read ${LANE}/scripts/source-capture.mjs and ${LANE}/.ufo/pins/source-captures.json (version 1; entries {sourceId, path, sha256, bytes, captured}; exemptions). The two captures live at ${CAP}/bailian-managed-agents-multiagent.md and ${CAP}/arxiv-2512.08296v3.html; the L1 will move them to .ufo/waves/round-63/build/ScoutCapture… if you say a different path is conventional (check the existing entries' path style, e.g. S195's). Compute sha256 and byte sizes yourself and write the two JSON entries (sourceId S196 for Bailian, S197 for arXiv; captured 2026-10-25) to ${B}/K63ExecCapturePins/pins-append.json. In a scratch mirror (copy of ${LANE}/.ufo/pins + the two captures + a stub SOURCES.md containing rows S196/S197 from ${B}/K63ExecRowDraft/append-block.md if it exists by then, else hand-written minimal rows) run node ${LANE}/scripts/source-capture.mjs against the mirror and paste its verdict. Then falsify: edit one capture byte in the mirror and show DRIFT. Also state how many bytes the arXiv html capture is against the 1 MiB new-file warning of the commit helper.`, ['operability'], 'capture pins');

add('K63ExecReadmeMapRepair', 'executor', `Repair plan for the base readme-map DRIFT, tested in a scratch mirror.
Base state: ${LANE}/.ufo/waves/round-63/base/readme-map-before.txt (round-62-verifier-spotcheck.md unmapped — the R56-V3 class, now the eighth recurrence). 1. Mirror ${LANE}/corpus, ${LANE}/.ufo/pins/readme-map.json and ${LANE}/scripts/readme-map.mjs under ${B}/K63ExecReadmeMapRepair/mirror/; add the README coverage-map row (same cell style as the neighbouring lessons rows, citing real S-ids / paths) and the 'covered' pin for corpus/lessons/round-62-verifier-spotcheck.md; run readme-map.mjs in the mirror; paste verdict. 2. Do the same dry-run for the files this round adds: corpus/knowledge/multi-agent-coordinator-topologies.md, corpus/lessons/round-63.md and corpus/lessons/round-63-verifier-spotcheck.md (the closure will land the last one after the lane's report, with its own writer — show what state readme-map reads between those two landings). 3. Propose a STRUCTURAL fix for the recurrence (e.g. the gate treating '*-verifier-spotcheck.md' as covered by a single row, or the closure helper adding the row) and show, with a mutated mirror, whether the proposed rule can still fail on a real unmapped lesson (a fix counts only if shown able to fail). Output ready-to-apply diffs under ${B}/K63ExecReadmeMapRepair/. Do not edit the lane.`, ['operability'], 'readme-map repair + structural fix');

add('K63ExecProxyStanza', 'executor', `Repair plan for the base proxy-check FAIL-CLOSED, tested in a scratch mirror.
Base state: ${LANE}/.ufo/waves/round-63/base/proxy-before.txt — 'GATE_PIN_KEY_UNKNOWN: pin.make-dispatch-actual is not a kumitate-gate-pins-v1 key' (round 62 added the pin to ${LANE}/SCORECARD.md's kumitate-gate-pins-v1 block without adding the key to GATE_PINS in ${LANE}/scripts/proxy-check.mjs). 1. Copy the lane to ${B}/K63ExecProxyStanza/mirror/ (use git -C ${LANE} archive ${FREEZE} | tar -x). In the mirror: add GATE_PINS keys 'pin.make-dispatch-actual' -> scripts/make-dispatch-actual.mjs and 'pin.inline-dispatch-evidence' -> scripts/inline-dispatch-evidence.mjs (with round comments like the neighbours), add the new pin line for the inline gate, recompute every stanza term the code derives (A, C, C2, C2_total, the pin.proxy-check sha256 AFTER your proxy-check edit — proxy-check pins itself — and the new gate pin), and run node scripts/proxy-check.mjs in the mirror until it reads MATCH (paste the full line and exit code). 2. Check proxy-check's own --selftest still passes after the key additions (paste the final line), and that the selftest has a case for a known vs unknown gate pin key. 3. Write ${B}/K63ExecProxyStanza/recompute.sh: given a lane dir it prints the stanza values the code derives (so the L1 can re-run it after the final file set exists — A counts every .mjs/.js/.sh/.py file in the lane tree incl. .ufo/waves probes; C2 counts corpus *.md). Output the diff of scripts/proxy-check.mjs and the stanza lines. Do not edit the lane.`, ['operability'], 'proxy-check repair');

add('K63ExecCounterReplay', 'executor', `Independent replay of the frozen counters and controls at the freeze commit.
1. Make a sandbox clone: D=$(mktemp -d) && git clone -q ${LANE} "$D"/lane (git -C "$D"/lane rev-parse --show-toplevel must equal "$D"/lane; do NOT commit anywhere); git -C "$D"/lane checkout --detach ${FREEZE} is NOT allowed in the lane itself but is fine inside your clone. 2. In the clone run, three times each: node .ufo/waves/round-63/probe/topology63-probe.mjs "$D"/lane ${FREEZE} (expect UNMET: entry absent) and node .ufo/waves/round-63/probe/inline63-probe.mjs "$D"/lane ${FREEZE} (UNMET: no waves yet). 3. Re-run the control generators in the clone: node .ufo/waves/round-63/probe/make-topology-controls.mjs "$D"/lane ${BASE} ${B}/K63ExecCounterReplay/topology-controls and confirm the same AS-EXPECTED/UNEXPECTED rows as ${LANE}/.ufo/waves/round-63/controls/topology/summary.txt (the fixture revisions differ; the verdict lines modulo rev= must agree). 4. Run the inline control cases through the gate again and diff against ${LANE}/.ufo/waves/round-63/controls/inline-receipts.txt. 5. Report flakiness: any run-to-run disagreement (live fetch variance for T5) and the wall time of each probe. Delete the sandbox when done.`, ['operability', 'coverage'], 'frozen counter replay');

add('K63ExecTranscriptStats', 'executor', `Ground the gate's structural thresholds in data: measure the real host transcripts.
The harness stores one JSONL per seat under ~/.omp/agent/sessions/<orchestrator-session>/<Seat>.jsonl (and -N respawn suffixes). Write ${B}/K63ExecTranscriptStats/stats.mjs (node) that, over every .jsonl at depth <= 3 (skip files > 50 MB, read-only), extracts per file: name, lane guess (from the user message), bytes, count of message rows by role, toolResult count, toolCall count by name, whether a 'yield' tool call exists, 'session_exit' kind, model_usage custom rows, first/last timestamp and span in seconds, id uniqueness. Output ${B}/K63ExecTranscriptStats/stats.tsv and a summary: how many seats finished (yield + normal exit) vs died (no yield / non-normal exit / no exit record), the distribution (min, p5, median) of bytes, toolResult count and span among FINISHED seats, the number of respawn-suffixed files, and any finished seat that lacks the structural properties a cheap forgery would also lack. State exact thresholds that no finished real seat violates (e.g. >= k toolResults) with the number of seats tested. Do not print transcript content; counts only (transcripts may contain secrets — Q5 shape-only).`, ['operability'], 'real transcript statistics');

add('K63ExecDeadSeatAudit', 'executor', `Considerthese 2026-10-25 self-improvement idea 3 ("audit seat deaths"), grounded by opening the instances: for rounds whose seat records exist in this lane (${LANE}/.ufo/waves/round-5*/ and round-6*/ — launcher-progress.tsv, *.err, swarm-registry.json, and for run-7 rounds the results.json + report files) list every dead seat (exit != 0 or session=null or a seat with no report file) and whether the round's filed report (${FLEET}/.ufo/reports/round-<N>/kumitate.md) names it with its error text. Output ${B}/K63ExecDeadSeatAudit/audit.tsv (round | seat | evidence of death | named in report? | error text present?) and the count of unnamed dead seats per round. Draw the evidence-based conclusion: for how many rounds does an unnamed dead seat exist (round 60 is the known case: 27 dead, 1 named). Then state the exact command the lane can run to produce this list for round 63 from the new gate (${ROUTE.gate} --report <report> reports DEAD_UNNAMED) and run it against the round-60 and round-62 reports where a dispatch record allows; say where it cannot.`, ['operability'], 'considerthese: dead-seat audit');

add('K63ExecQualityCommand', 'executor', `Mistake-mining command, shown able to fail (round 62's mistake: the lane read "the prompt contains no claim sentences" as "no claims declared" and filed a zero-claim round — captured-by: none).
Define and run the check "a round's plan file is committed in the lane BEFORE the round's first wave .ready marker": for round R: the first lane commit touching .ufo/waves/round-R/plan.md (git -C ${LANE} log --diff-filter=A --format=%H%x09%ct -- .ufo/waves/round-R/plan.md | tail -1) must exist and be an ancestor-or-equal of the first commit that adds any .ufo/waves/round-R/*.ready (or any <wave>-dispatch.json if no .ready) and its commit time must be <= that commit's time. Write ${B}/K63ExecQualityCommand/plan-before-ready.sh implementing it with explicit exit codes (0 pass, 1 fail, 2 round has no plan/wave data). Run it for rounds 50-63 and tabulate pass/fail/NA with the commit hashes; round 62 must FAIL (no plan.md) and round 63 must PASS only once the .ready for wave 1 is committed (today ${FREEZE} precedes any marker). Also run it against a deliberately wrong fixture (fixture repo rules in the context) where the marker commit precedes the plan, and show FAIL. Report the table and the command text the QUALITY criterion will quote.`, ['operability'], 'mistake-mining command');

add('K63ExecWaveCensus', 'executor', `Operability check: can the lane's existing wave-census read a run-7 inline wave?
Run node ${LANE}/scripts/wave-census.mjs (read its header for the CLI) against the committed round-61 dispatch evidence (${LANE}/.ufo/waves/round-61/w1-dispatch.json, w2-dispatch.json) and against this round's dispatch artifact once it exists — it will not exist yet at wave start, so use round 61 and the frozen specs under ${LANE}/.ufo/waves/round-61/. Report: does wave-census accept the validator's ufo-swarm-wave-dispatch-v1 taskCall shape the inline handoff consumes; what does it report for the seats-per-role and the reports at each 'Report:' path; does it need changes for the inline results file (<wave>-results.json) — list the gaps vs ${ROUTE.gate}. Do not edit scripts; give a patch proposal only if the gap is a bug.`, ['operability'], 'wave-census inline compatibility');

// ======================= SCRIBES (6) =======================
add('K63ScribeEntryDraft', 'scribe', `Draft the knowledge entry the round adopts (draft A). The captures are fixed bytes: ${CAP}/bailian-managed-agents-multiagent.md (S196, Chinese, vendor coordinator contract) and ${CAP}/arxiv-2512.08296v3.html (S197, "Towards a Science of Scaling Agent Systems", arXiv:2512.08296v3). Starting text (staged, to be RE-GROUNDED, not trusted): ${ST}. Read ${LANE}/corpus/QUALITY.md Q1-Q9 and one admitted entry for house style (${LANE}/corpus/knowledge/bounded-redelivery-budgets.md). Output ${B}/K63ScribeEntryDraft/entry.md as the complete final file, <= 120 lines:
- Header lines first: "source: S196 — <url> — <section anchor>" and "source: S197 — https://arxiv.org/html/2512.08296v3 — <section anchor>", "verified-at: 2026-10-25" (plus the version/date observed), "recheck: 90d — <a re-runnable command whose output you ran>", coverage-map and ground lines as in the style entry.
- Sections: Scope (what this entry covers and what S018/MAST and S131 already cover); the contract (roster of 1-20, self at most once, version pin, single-agent fallback); the measured cost (only numbers present in the capture; give the section of the paper each comes from; mark anything not in the capture UNKNOWN or cut it); the decision rule that follows (task structure decides, not agent count) with an explicit [INFERENCE] label on any step the sources do not state; a Limits section naming skew (the page is a vendor doc dated by fetch, the paper is preprint v3 of 08 Apr 2026, not peer-reviewed venue).
- A final "## Located quotes" section: >= 8 bullets in exactly the form  - S196 — "<quote>"  or  - S197 — "<quote>"  (ASCII double quotes, each <= 25 words, each verbatim in the capture after the normalisation the frozen counter uses: ${NORM}). Both S196 and S197 must have bullets. Prove every bullet with a script that exits nonzero on a miss and paste its output into your report. No template tokens like __X__; no unsupported number.`, ['coverage'], 'entry draft A');

add('K63ScribeEntryDraftB', 'scribe', `Draft the knowledge entry the round adopts (draft B — independent of draft A, deliberately different organisation: lead with the decision table). Same captures and constraints as the entry task: ${CAP}/bailian-managed-agents-multiagent.md (S196) and ${CAP}/arxiv-2512.08296v3.html (S197); staged text ${ST} to be re-grounded; style entry ${LANE}/corpus/knowledge/bounded-redelivery-budgets.md; QUALITY Q1-Q9 in ${LANE}/corpus/QUALITY.md. Output ${B}/K63ScribeEntryDraftB/entry.md, <= 90 lines, complete file, headers "source:" (one line per row, with section anchors), "verified-at: 2026-10-25", "recheck:" with a command you ran, then a table "if the task looks like X, prefer topology Y, because (S197 section)" using ONLY findings in the paper's capture, a short roster-limits table from S196, a Limits section, and "## Located quotes" with >= 8 bullets "- S196 — \\"…\\"" / "- S197 — \\"…\\"" (each <= 25 words, each verbatim in its capture after the frozen counter's normalisation: ${NORM}). Run a script proving every bullet is found and paste the output. Mark every step the sources do not state [INFERENCE]. End your report with a 5-line comparison of what B says that a literal reading of the staged entry would have over-claimed.`, ['coverage'], 'entry draft B');

add('K63ScribeLesson', 'scribe', `Draft ${LANE}/corpus/lessons/round-63.md as a full file at ${B}/K63ScribeLesson/round-63.md. Read the house style of ${LANE}/corpus/lessons/round-61.md and round-62.md (sections: opened-source recheck / Assimilation / Gate table / Census before→after / Mistakes / stripped-prose records). Use ONLY facts you can verify now from committed bytes (${FREEZE}); wherever a fact belongs to a later step write the literal token {{L1:<what>}} (never __X__ tokens). Required content: (1) ## Assimilation — theme coordinator topology, access date 2026-10-25, plan pointer .ufo/waves/round-63/plan.md; the id collision result (reg 134 ids, staged 155, collisions: S195 only; renumber map package S200 -> lane S196, package S202 -> lane S197; paths under .ufo/waves/round-63/assimilation/); (2) ## Gate table with columns candidate | decision | criterion/reason | located evidence: the ADMIT row for multi-agent-coordinator-topologies.md (with {{L1:quote}} placeholders for the located quote cell) and a REJECT row {{L1:rejected staged entry}} with flip condition; also the carried exactly-once-attribution.md reject (rounds 60/61, flip unchanged); (3) ## Quarantine — 9 rows, verdicts {{L1:scout verdicts}}; (4) ## Census before → after — before is the committed receipt ${LANE}/.ufo/waves/round-63/base/census-before.txt (exit 0, 134 rows, six W04 warnings), after {{L1}}; (5) ## Mistakes — class · evidence pointer · captured-by · fix, for the round-62 zero-claim misreading (evidence ${LANE}/corpus/lessons/round-62-verifier-spotcheck.md §Verdict and routed defect 1; captured-by none; fix = a QUALITY criterion with a command shown able to fail, {{L1:criterion id}}); (6) ## Considerthese — idea 3 of ${LANE}/considerthese/2026-10-25.md and what was done. Output the file and a list of every {{L1:…}} token.`, ['coverage'], 'lesson draft');

add('K63ScribeQuality', 'scribe', `Draft two QUALITY criteria to append (append-only, house style of Q54-Q57 in ${LANE}/corpus/QUALITY.md lines ~924-950: Grounding / Who checks / Command / Fails when / Shown able to fail / Limit). Output ${B}/K63ScribeQuality/criteria.md.
Q58 — a round's plan file (claims, frozen predicates, controls) is committed in the lane before the round's first wave marker. Grounding: ${LANE}/corpus/lessons/round-62-verifier-spotcheck.md (routed defect 1; round 62 declared no claims). The command and its demonstration come from the executor seat K63ExecQualityCommand (${B}/K63ExecQualityCommand/ — it may not exist yet: write the criterion around the one-line git commands named in the plan-before-ready rule, and mark the 'Shown able to fail' line {{L1:command results}} for the L1 to fill).
Q59 — a dispatch claim is backed by host records the lane does not author: session transcripts per seat, the orchestrator dispatcher log, committed bytes only; the dead-seat set from transcripts is named in the report (considerthese 2026-10-25 idea 3, grounded in ${LANE}/corpus/lessons/round-60-verifier-spotcheck.md R60-V5/V6). Command: node scripts/inline-dispatch-evidence.mjs --root ${LANE} --rev <tip> --round <N> --wave <w> --report <fleet report> exit 0 with dead names present; Fails when: transcript absent/foreign/ambiguous/duplicate id, spawn/done log lines missing or mismatched, a dead seat unnamed, a report tiny/duplicate. Shown able to fail: the 14 controls (${LANE}/.ufo/waves/round-63/controls/inline/) and the real-host sweep ${LANE}/.ufo/waves/round-63/controls/inline-real-hosts.txt. Limit: the stated limit in plan.md (a lane that writes both host records). Keep each criterion <= 12 lines. No template tokens other than {{L1:…}}.`, ['operability'], 'quality criteria draft');

add('K63ScribeSkillProvince', 'scribe', `Draft the lane documentation text for the new gate and the new frontier band; the L1 pastes it. Read ${LANE}/SKILL.md (find the '## Gate registry' table and the '## Verifiable checklist' numbered items; list the exact current last rows), ${LANE}/PROVINCE.md (the Frontier bullets) and ${LANE}/corpus/README.md (## Frontier, coverage map). Output ${B}/K63ScribeSkillProvince/drafts.md with: (1) the SKILL.md gate-registry row for scripts/inline-dispatch-evidence.mjs in the same column style as scripts/dispatch-evidence.mjs (contract, verdicts, exit codes, what it binds, the selftest line 'INLINE_DISPATCH_SELFTEST: PASS (25/25)'); (2) one SKILL.md checklist item (command + stated outcome) — note the proxy term C counts checklist items, so say precisely how adding it moves C and that the L1 must decide; (3) the PROVINCE.md Frontier bullet for multi-agent coordinator topology that names the path corpus/knowledge/multi-agent-coordinator-topologies.md on the same line, uses the words 'frontier' or 'first entry', cites S196/S197 and frames the entry as orchestration topology DECISIONS (adjacent: kengaku evaluates agents; this lane decides how seats are arranged); (4) the corpus/README.md coverage-map row for the entry, and the Frontier-section sentence. Only facts present in committed bytes; {{L1:<what>}} for the rest.`, ['coverage'], 'documentation drafts');

add('K63ScribeScorecard', 'scribe', `Draft the SCORECARD.md additions as ${B}/K63ScribeScorecard/scorecard-additions.md. Read ${LANE}/SCORECARD.md: the '## Capabilities' table (row style of 'dispatch-evidence' and 'readme-map'), the late sections 'Round 61 — claims, verdicts, limits' and 'Round 62 — honest stop …' (house style), and '## Saturation'. Write: (1) the capabilities row 'inline-dispatch-evidence' (what it can now do, evidence pointer = the counting command and selftest line, first-working round 63 — only entered if C1 is HELD; mark the row text {{L1:enter only if HELD}}); (2) a '## Round 63 — claims, verdicts, limits (2026-10-25)' section skeleton citing plan .ufo/waves/round-63/plan.md frozen at ${FREEZE}, C1 and C2 with counting commands, before values (INLINE63_UNMET held=0/6; TOPOLOGY63_UNMET held=1/7 at ${BASE}), controls, waves, and {{L1:after}} tokens; (3) an append-only correction paragraph retiring the inherited dispatch61/doctrine61 predicates (R61-V2) in favour of INLINE63/TOPOLOGY63, naming what carries their forgeries (controls); (4) a '## Saturation' paragraph for round 63 (stagnation window: the last verified capability is round 59). No numbers that are not in committed bytes.`, ['operability', 'coverage'], 'scorecard drafts');

// ======================= SIMPLIFIER (1) =======================
add('K63SimplifyTool', 'simplifier', `YAGNI review of the new gate and the two frozen probes: ${ROUTE.gate}, ${ROUTE.c1probe}, ${ROUTE.c2probe}. For each: list dead code, duplicated logic, unreachable branches, flags with no caller or test, comments that restate code, and anything the selftest or controls never exercise. Work on copies under ${B}/K63SimplifyTool/ and prove with the selftest (node <copy> --selftest) that every proposed deletion keeps behaviour: for the gate, the 25-case selftest and the 14 control cases (run each control through the copy) must keep reading as before. Never edit the originals; the probes are frozen, so for them report only (do not propose edits that change a verdict). Output the unified diff for the gate only, with the line-count delta.`, ['operability'], 'simplification');

// ======================= ATTACKERS (10) =======================
add('K63ReviewGateCode', 'reviewer', `Line-by-line correctness review of ${ROUTE.gate} (committed at ${FREEZE}). Hunt: RegExp built from file data (lane/round/wave come from ready.json and argv: injection or catastrophic backtracking), path traversal through the wave name or a seat name containing '/' or '..' in reads of \`.ufo/waves/round-N/<wave>/<name>.md\` and in candidates() (stem matching with '-' + digits — a seat 'K63Foo' vs 'K63Foo-2' vs 'K63Foo-2-3'), tail()/includes() matching on short or empty task text, transcripts read whole into memory (9 MB+; 50 MB?), parse errors swallowed so a corrupt transcript becomes 'foreign' vs 'absent', the exit code mapping (0/1/2/64), --rev handling when the rev is a branch name that moves, reading with maxBuffer, dead-seat logic (yield + session_exit normal) vs a seat that yielded twice or exited 'dispose' (the real normal exit record is {kind:'normal', reason:'dispose'} — check against real transcripts), the 'done' log regex anchoring, and the case where results.json lists a seat the dispatch lacks. For each defect give a reproducing command (fixture under /tmp, fixture-repo rules in the context) and a minimal patch as text in your report. Severity-order them.`, ['operability'], 'attack: gate code');

add('K63ReviewProbeC1', 'reviewer', `Attack the frozen C1 counter ${ROUTE.c1probe} (rule I63 v1): can a do-nothing or forging commit reach INLINE63_HELD held=6/6 without any seat having run? Read the probe, the plan (${LANE}/.ufo/waves/round-63/plan.md) and the controls. Check specifically: I1 selftest runs from the archive (is the selftest itself able to pass vacuously?); I2 loops over committed '*-results.json' (what if the commit has none for round 63 other than a hand-written one — does the host-transcript read in the gate actually bind it?); I3 reads fixtures from the archive (a forger can add fixtures that expect whatever they like — does the probe check the cases' content, only the count?); I4 minimal pair; I5 SCORECARD row regex (a row inside a code fence or another section?); I6 circular tip receipt (the receipt line can be hand-typed — what does it add?). For each hole write the cheapest exploit as a concrete recipe and the check that would close it. Do not change the probe: frozen holes are reported so the L1 can ratchet controls/gate or declare the limit honestly in the report.`, ['operability'], 'attack: C1 counter');

add('K63ReviewProbeC2', 'reviewer', `Attack the frozen C2 counter ${ROUTE.c2probe} and its control generator ${LANE}/.ufo/waves/round-63/probe/make-topology-controls.mjs (rule T63 v1). Read both and ${LANE}/.ufo/waves/round-63/controls/topology/summary.txt. Probe for: norm() leniency (stripping tags and '*', '_' pairs, mapping dashes: can a quote that is NOT in the page match after normalisation? e.g. a quote built from fragments across a table cell, from <script> content kept in the capture, or from text inside HTML comments; can a 25-word limit be gamed by counting rule — split on whitespace); T2's NF=13 row regex vs a row with an escaped pipe; 'used-by names the entry' by substring (a different path containing the entry path as a substring); T3 trusting source-captures.json entries a forger adds with their own sha; T4 bullets whose quote is trivially present (a 3-word quote 'the' passes — is there a minimum length?); T5 live check on a URL the forger controls (the row's URL field is lane-written: a forger can point the row at a page they host — what binds the URL to the claimed source?); T6/T7. For each hole, the cheapest exploit recipe and the closing check. Reports only — the counter is frozen; the L1 will ratchet through additional controls or state the limit.`, ['coverage'], 'attack: C2 counter');

add('K63ReviewQuotes', 'reviewer', `Fact-check the staged entry's numeric claims against the arXiv capture and re-derive the claim the round will make. Read ${ST}, ${CAP}/arxiv-2512.08296v3.html, ${CAP}/bailian-managed-agents-multiagent.md. Independently (without reading the scout/scribe reports) answer, with located text for each: what does the paper say about Terminal-Bench and SWE-bench Verified (Appendix F; the staged entry says SWE-bench -15% to -2%, Terminal-Bench independent +2% and centralized -19%: are these in v3 and under which table/section), what are the percentages for Workbench and BrowseComp-Plus, what does the paper say about the cost formulas, and does 'tasks where single-agent accuracy exceeds 45% see negative returns' apply to 'most models'? Then list each staged claim as VERIFIED / NOT-FOUND / CONTRADICTED. A claim you cannot locate is NOT-FOUND, never 'plausible'. Cut-list for the entry. Include the exact byte offsets (grep -b on the normalised text) so a closure seat can re-find each.`, ['coverage'], 'attack: staged numbers');

add('K63CriticC1Predicate', 'critic', `Falsify claim C1 as declared. Read ${LANE}/.ufo/waves/round-63/plan.md (C1) and the frozen counter. Build, in scratch fixtures under /tmp/kumitate-r63/K63CriticC1Predicate/ (fixture repo rules in the context), the cheapest do-nothing control that skips the claimed work and see how far it climbs: (a) a lane commit with no tool at all; (b) a commit that copies scripts/inline-dispatch-evidence.mjs but fabricates waves with hand-written results/ready/markers/reports; (c) the same plus hand-written transcripts in a scratch sessions root (is the default host root consulted by I2?); (d) a commit whose tool is a stub printing the expected selftest line. For each, run the real probe against the fixture commit and paste the verdict line. Then answer: is the claim's target reachable by a do-nothing control? What exact sentence in the plan would you change if you could (report only)? Honest controls too: run the probe on a clean fixture of this lane at ${FREEZE} (expect UNMET with the I-checks that cannot hold yet).`, ['operability'], 'attack: C1 claim');

add('K63CriticC2Predicate', 'critic', `Falsify claim C2 as declared. Read ${LANE}/.ufo/waves/round-63/plan.md (C2), the frozen counter ${ROUTE.c2probe} and the committed controls. In a fixture repo (rules in the context) built from git -C ${LANE} archive ${FREEZE}, build the cheapest forgeries the eleven committed controls do NOT cover and run the real counter on each: (a) an entry whose quotes are real but whose claims are invented (the counter cannot read semantics — measure and state this limit); (b) a row URL pointing at an attacker-hosted copy of the page; (c) a quote that matches only through the normaliser; (d) two rows that are the same document under different ids (duplicate-document class); (e) a capture of the wrong version of the paper (v1 instead of v3) with a matching pin; (f) a phantom second row cited but the entry only really using one. Paste verdict lines. For each forgery the counter reads HELD, say whether it is a counter hole to ratchet or an irreducible limit to state.`, ['coverage'], 'attack: C2 claim');

add('K63CriticFreezeIntegrity', 'critic', `Attack the freeze itself. Verify, from committed bytes only (git -C ${LANE} show/ls-tree/log at ${FREEZE}): the plan's sentences equal the code's conditions and the receipts' labels (C1 I1-I6 in ${ROUTE.c1probe}, C2 T1-T7 in ${ROUTE.c2probe}; check every number: 25, 32, 64, 100, 10, 6, 7), the base receipts (${LANE}/.ufo/waves/round-63/base/*.txt) are what the probes print at ${BASE} (re-run both against ${BASE} in a sandbox clone and diff), counter-pins registry carries the four new pins and counter-pins.mjs reads CLEAN, the plan claims '14 fixtures' and '25 selftest cases' (count them), the inline-real-hosts.txt lines were produced by the committed gate (re-run two), nothing else changed between ${BASE} and ${FREEZE} (git diff --stat ${BASE} ${FREEZE}), and the plan's 'Before' values equal the receipts. Also test the do-nothing rule for the PLAN: is any predicate satisfiable without moving the surface it names? List every plan sentence a reader could not re-derive with one command.`, ['operability', 'coverage'], 'attack: freeze integrity');

add('K63MutateInlineGate', 'mutation-tester', `Mutation-test the gate against the committed evidence (selftest + 14 controls + real-wave readings). Copy ${ROUTE.gate} to /tmp/kumitate-r63/K63MutateInlineGate/work/, apply >= 25 single-edit mutants to inspect() (flip comparisons, drop a finding push, change thresholds, swap && / ||, remove a guard) — one at a time, never touching the original — and for each run: the copy's --selftest; the 14 control cases in ${LANE}/.ufo/waves/round-63/controls/inline/ (gate args as in controls/inline-receipts.txt); and the real kengaku r35 build wave (--root /home/vgpnk/Projects/shokunin/kengaku-shokunin --round 35 --wave build). A mutant SURVIVES if selftest, controls and the real wave all read as before. Output the table (mutant | selftest | controls | real | verdict) and, for each survivor, the control directory (lane/, sessions/, dispatcher.log, expect in the layout of controls/inline/<case>/) that would kill it — write those directories under /tmp/kumitate-r63/K63MutateInlineGate/new-controls/ and copy the path list into your report (the L1 may promote them into controls/inline/ as ratchet cases). Report the kill rate honestly.`, ['operability'], 'attack: gate mutation');

add('K63MutateProbes', 'mutation-tester', `Mutation-test the two FROZEN counters against their committed controls: ${ROUTE.c1probe} and ${ROUTE.c2probe}. Copy each to /tmp/kumitate-r63/K63MutateProbes/ and apply >= 12 single-edit mutants per probe to its check logic (e.g. drop T5 so live is skipped, relax N >= 25 to >= 0, change 6/7 held counts, accept stale opened dates, drop the used-by check, loosen the I3 case-count floor, skip the tip-receipt compare). For C2 the committed control set is ${LANE}/.ufo/waves/round-63/controls/topology/ (re-run a mutated probe over the same fixtures with make-topology-controls.mjs's logic — copy the generator, point it at the mutated probe; the generator takes the lane dir, so place the mutant at .ufo/waves/round-63/probe/topology63-probe.mjs inside a sandbox clone of ${FREEZE}). A mutant of a probe SURVIVES if every control still reads as expected. For C1 the controls are ${LANE}/.ufo/waves/round-63/controls/inline/ (checked by I3) — mutants of I1/I2/I4/I5/I6 cannot be killed by I3 and the base receipt only; say so and propose the control each would need. Table + survivors + the control that would kill each. No edits to the frozen files.`, ['operability', 'coverage'], 'attack: counter mutation');

add('K63MutateTopologyControls', 'mutation-tester', `Mutation-test the CONTROL SET of C2 (not the counter): is each of the eleven fault variants really independent? In a sandbox clone of ${FREEZE} (git clone, fixture rules), for each variant in ${LANE}/.ufo/waves/round-63/probe/make-topology-controls.mjs, apply ONLY its mutation to the honest fixture and confirm exactly the arm it claims turns MISS and no other arm masks it (read the verdict lines in ${LANE}/.ufo/waves/round-63/controls/topology/*.txt: f2 and f3 and f6 show several MISS arms — say whether the expected arm would still be MISS if the others were fixed). Then add variants the set lacks — at least six new single-fault fixtures (duplicate cited S-id counted twice, bullet quote of length 1-3 words, row URL changed to another host while the capture stays, a capture path outside the repo like ../, source-captures.json entry for the row missing, PROVINCE line naming a different path that contains the entry path as a prefix) — by writing a generator copy ${B}/K63MutateTopologyControls/more-controls.mjs that reuses the honest fixture construction, runs the frozen counter on each, and writes verdict lines. Report which new variants the frozen counter wrongly reads HELD (counter holes) vs UNMET.`, ['coverage'], 'attack: control independence');

add('K63SentinelScope', 'sentinel', `Security and scope review of the round's committed artifacts and the gate's host access. (1) The gate reads host session transcripts under ~/.omp/agent/sessions (they can hold secrets, API output, file contents): confirm it never prints or commits transcript content, only counts/ids/booleans (read ${ROUTE.gate}); confirm no committed round-63 file under ${LANE}/.ufo/waves/round-63/ contains a transcript excerpt or a host-session path beyond a directory name (grep -rEn for 'sk-', 'Bearer', 'token', 'password', 'api[_-]?key', the home directory path to sessions, /fast/scratch paths); (2) check the freeze commit's file list (git -C ${LANE} show --stat ${FREEZE}) for anything outside the lane write scope or any file >1 MiB (the helper skips >1 MiB new files: the arXiv html capture is 663,997 bytes); (3) check the control generators write only under their given out-dir and mktemp (read make-inline-controls.mjs, make-topology-controls.mjs: rmSync(out) with a user-supplied path — can a bad argument delete something outside? what if out is '/' or the lane root?), and that make-topology-controls.mjs's fixture git calls all name -C "$D" and verify the toplevel; (4) the live-fetch arm of the C2 counter (curl to URLs read from lane-written rows: SSRF-style file://, redirects, unlimited size, --max-time) — attack it and propose the guard; (5) seat write-scope: list which w1 seat prompts could cause writes outside their report/build paths. Severity-ordered findings with reproducing commands.`, ['operability'], 'attack: security and scope');

add('K63RevengerDispatcher', 'revenger', `Reverse-engineer how the orchestrator's inline dispatcher names and stores seats, so the gate's SESSION_AMBIGUOUS / -N suffix semantics are grounded. Read /fast/scratch/hyaku-run7/dispatcher.py and dispatcher.log (read-only; run nothing in it), the harness session store layout ~/.omp/agent/sessions/<orchestrator-session>/ (JSONL per seat, <Seat>.md, <Seat>-2.jsonl, directories like KengakuR33/), and the transcripts themselves (counts/headers only — shape, no content dump). Answer with evidence: (1) what produces '<Name>-2.jsonl' (a resume? a label collision? an L1 resend? the dispatcher's 'already spawned' skip?) — find a concrete instance (tameshi r45 ExecRows01, -2, -3) and the dispatcher.log lines around it; (2) what does the jsonl 'session' header 'parentSession' point at, and is it the same for all seats of a round; is the id unique per seat; (3) what is the real final record of a finished seat ('yield' tool call, 'session_exit' {kind:'normal', reason:'dispose'}?) and of a seat killed mid-run — find examples of each (counts of each exit kind across the store); (4) whether a seat's user message always contains '# Seat <name>' followed by a newline and the verbatim context head, as dispatcher.register() composes it, including seats of older dispatcher versions (kaidoku r35, souji r26: why does the gate read sessions=0 for them). Output a short spec the gate can rely on, flagging anything the gate currently assumes but the data contradicts.`, ['operability'], 'reverse-engineer: dispatcher');

writeFileSync(new URL('./w1-items.json', import.meta.url), JSON.stringify(items, null, 1));
const spec = {
  wave: 'kumitate-r63-w1',
  context: context('w1', 'build + first falsifiers'),
  reportDir: '.ufo/waves/round-63/w1',
  maxLanes: 64,
  items,
};
writeFileSync(new URL('../w1-spec.json', import.meta.url), JSON.stringify(spec, null, 1));
const counts = {};
for (const i of items) counts[i.role] = (counts[i.role] || 0) + 1;
process.stdout.write(`${items.length} seats ${JSON.stringify(counts)}\n`);
